Definition fini_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 304, bv_unsigned sp); (0x241450, 0x241451); (0x241400, 0x241408); (0x242370, 0x242378);
              (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x7771a0, 0x7771a3); (0x777140, 0x777142)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Lemma fini_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (o1 o2 o3 o4 o5 : byte) (flag dso : word),
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 304 -> 0x800f0000 <= lo ->
  ro_cells asegs m 0x21f580 [C8 (Z_to_bv 64 0xfae10); C8 (Z_to_bv 64 0xa001c)] ->
  ro_cells asegs m 0x226ba0 [C8 (Z_to_bv 64 0x21f590); C8 (Z_to_bv 64 0x21f580)] ->
  ro_cells asegs m 0x225cf0 [C8 (Z_to_bv 64 0x20736c); C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x227c20 [C8 dso] ->
  ro_cells asegs m 0x2269c8 [C8 (Z_to_bv 64 0x22aa90); C8 (Z_to_bv 64 0x2413d0)] ->
  rw_cells asegs m 0x241450 [C1 (Z_to_bv 8 0)] ->
  rw_cells asegs m 0x241400 [C8 flag] -> bv_unsigned flag <> 0 ->
  unreg_got m ->
  ro_cells asegs m 0x2422d0 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x242370 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x244ab8 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x245798 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x24431c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x2d6660 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x227e98 [C8 (Z_to_bv 64 0x218338)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x22aa90 asan_gds ->
  rw_cells asegs m 0x7771a0 [C1 o1] -> rw_cells asegs m 0x777140 [C1 o2] -> rw_cells asegs m 0x777141 [C1 o3] -> rw_cells asegs m 0x7771a1 [C1 o4] -> rw_cells asegs m 0x7771a2 [C1 o5] ->
  mem_inv asegs m ->
  evt asegs (fini_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
